//! `cargo xtask editors [--check]`: generate the editor grammars from the parser's vocabulary.
//!
//! The vocabulary (directives, keywords, shells, layouts, key names and modifiers) is read from the
//! code that implements the language, so adding a layout or keyword in Rust reaches every editor
//! target. `--check` fails if a committed generated file is stale, and runs as a test too.

mod vocabulary;

use std::path::Path;
use std::path::PathBuf;
use std::process::ExitCode;
use vocabulary::Vocabulary;

/// Put at the top of every generated file, in whatever comment syntax the file has
pub const GENERATED_NOTICE: &str = "Generated by `cargo xtask editors`. Do not edit.";

/// Every generated file, relative to the repository root, with its contents
pub fn generated_files() -> Vec<(PathBuf, String)> {
    let vocabulary = Vocabulary::load();

    vec![(
        PathBuf::from("editors/vocabulary.json"),
        json(&vocabulary.to_json()),
    )]
}

fn json(value: &serde_json::Value) -> String {
    let mut out = serde_json::to_string_pretty(value).expect("vocabulary is valid json");
    out.push('\n');
    out
}

pub fn repository_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("xtask lives inside the repository")
        .to_path_buf()
}

/// Line endings do not matter: git on Windows may check files out with CRLF
fn normalise(text: &str) -> String {
    text.replace("\r\n", "\n")
}

/// The generated files that are missing or differ from what is on disk
pub fn stale_files(root: &Path) -> Vec<PathBuf> {
    generated_files()
        .into_iter()
        .filter(|(path, contents)| {
            std::fs::read_to_string(root.join(path))
                .map_or(true, |existing| normalise(&existing) != normalise(contents))
        })
        .map(|(path, _)| path)
        .collect()
}

fn write(root: &Path) -> std::io::Result<()> {
    for (path, contents) in generated_files() {
        let full = root.join(&path);

        let unchanged = std::fs::read_to_string(&full)
            .is_ok_and(|existing| normalise(&existing) == normalise(&contents));

        if unchanged {
            println!("{}: unchanged", path.display());
        } else {
            if let Some(parent) = full.parent() {
                std::fs::create_dir_all(parent)?;
            }
            std::fs::write(&full, contents)?;
            println!("{}: updated", path.display());
        }
    }

    Ok(())
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let root = repository_root();

    match args
        .iter()
        .map(String::as_str)
        .collect::<Vec<_>>()
        .as_slice()
    {
        ["editors"] => match write(&root) {
            Ok(()) => ExitCode::SUCCESS,
            Err(error) => {
                eprintln!("could not write the editor files: {error}");
                ExitCode::FAILURE
            }
        },
        ["editors", "--check"] => {
            let stale = stale_files(&root);
            if stale.is_empty() {
                println!("editor files are up to date");
                ExitCode::SUCCESS
            } else {
                for path in &stale {
                    eprintln!("{}: out of date", path.display());
                }
                eprintln!("run `cargo xtask editors` to regenerate them");
                ExitCode::FAILURE
            }
        }
        _ => {
            eprintln!("usage: cargo xtask editors [--check]");
            ExitCode::FAILURE
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_files_are_up_to_date() {
        let stale = stale_files(&repository_root());
        assert!(
            stale.is_empty(),
            "out of date: {stale:?}, run `cargo xtask editors` to regenerate"
        );
    }
}
